local zones = {
	[947] = {
		name = "Azeroth",
		short = "Ten thousand years ago the land of this world lay together in one continent, ancient Kalimdor. The Highborne drew recklessly on the magic of the Well of Eternity, and the ripples of it reached the Twisting Nether.",
		full = "Ten thousand years ago the land of this world lay together in one continent, ancient Kalimdor. The Highborne drew recklessly on the magic of the Well of Eternity, and the ripples of it reached the Twisting Nether. The Burning Legion took notice. Sargeras tempted Queen Azshara with power beyond measure, if only the Legion were summoned, and the Highborne opened a great gate in the depths of the Well.\n\nMalfurion Stormrage and the night elf resistance saw that the Well had become a doorway for Sargeras himself. Malfurion drew on the Dragon Soul and broke the ritual with a storm. Sargeras and most of his demons were flung back into the Twisting Nether. Then the Well collapsed, and the earth split beneath the survivors. Most of the old continent sank. Ruined continents rose from the wreck, and the drowned heart of the land became the Great Sea. The Maelstrom still turns where the Well once stood.",
		source = "https://warcraft.wiki.gg/wiki/Azeroth",
	},
	[1411] = {
		name = "Durotar",
		short = "Cracked and red, Durotar is a land of crags and canyons, dry and hot, sparse in water and green things. It lies on the eastern coast of Kalimdor.",
		full = "Cracked and red, Durotar is a land of crags and canyons, dry and hot, sparse in water and green things. It lies on the eastern coast of Kalimdor. The orcs find in it a harsh beauty that recalls Draenor. After the Third War, Warchief Thrall led his people here to build a new homeland, and he named it for his murdered father, Durotan.\n\nPeace did not last. Grand Admiral Daelin Proudmoore, a hero of the Second War and no friend to orcs, brought a great fleet from Kul Tiras against Durotar, determined to crush the Horde before it could take root. His daughter, Jaina Proudmoore, chose otherwise. At Theramore she turned against her own father to fight beside Thrall, and Daelin died in the battle before the two could reconcile. In gratitude, Thrall let Jaina's soldiers withdraw to Theramore unharmed.\n\nThe Darkspear trolls hold the southern coast as exiles. Their own witch doctor, Zalazane, drove them from their home in the Echo Isles, and they have not been able to take the isles back.",
		source = "https://warcraft.wiki.gg/wiki/Durotar_(Classic)",
	},
	[1412] = {
		name = "Mulgore",
		short = "The tauren wandered for hundreds of years with no land of their own. Then they met Thrall and his orcs when they landed on Kalimdor, and Cairne Bloodhoof saw kindred spirits with honor and power.",
		full = "The tauren wandered for hundreds of years with no land of their own. Then they met Thrall and his orcs when they landed on Kalimdor, and Cairne Bloodhoof saw kindred spirits with honor and power. With Thrall's escort Cairne led his people into Mulgore, and with the orcs' help the Bloodhoof tribe drove back the centaur and claimed the grasslands.\n\nIt is a sheltered valley, a great pasture of green grass and few trees, walled in by mountains on every side with a single pass leading out. In the middle, the cliffs of Thunder Bluff rise above the fields and throw long shadows across the plain. On that mesa Cairne built a refuge where tauren of every tribe are welcome, and the scattered tribes have united under his rule.\n\nTents and hide huts stand beside windmills that drive the grain mills. The centaur still raid the plains, but the mesa strongholds have held against them. Every tauren who comes of age must walk into the wilds of Mulgore and prove themselves in the Great Hunt.",
		source = "https://warcraft.wiki.gg/wiki/Mulgore_(Classic)",
	},
	[1413] = {
		name = "The Barrens",
		short = "The dust here was not always dust. This land was forest once, tended by the night elves, and several of their large cities stood here.",
		full = "The dust here was not always dust. This land was forest once, tended by the night elves, and several of their large cities stood here. After the Great Sundering, war and disaster turned the green valley into a sun-scorched plain. It is hot and mostly flat, with scattered hills and a few oases where the water gathers.\n\nFor countless generations the tauren roamed these plains, following the kodo and the thunder lizards. Centaur hunted them for sport. The tauren fought back when they had to, but they had no love of war and would rather strike their tents and move on. A year of peace was always followed by a year of war. Then Thrall's orcs and the Darkspear trolls came ashore and marched beside the Bloodhoof tauren against the centaur.\n\nNow the Horde holds most of it. Orc farms and watchtowers dot the grass, and the Gold Road runs through the land from north to south. Quilboar and centaur raid from every side, and Burning Blade cultists work in the north.",
		source = "https://warcraft.wiki.gg/wiki/Barrens_(Classic)",
	},
	[1414] = {
		name = "Kalimdor",
		short = "When the Highborne were gone, the night elves who stayed on the broken continent chose to shut themselves away. A veil of mist settled over the land and hid it from passing sailors.",
		full = "When the Highborne were gone, the night elves who stayed on the broken continent chose to shut themselves away. A veil of mist settled over the land and hid it from passing sailors. Among humans, Kalimdor lived on only as an old legend of a country that had broken and sunk beneath the waves. The high elves of Quel'Thalas knew better, since night elves visited them over the long years.\n\nEven when the Third War began, most humans still thought Kalimdor a story. The Kirin Tor's own ambassador at King Terenas' court was among the doubters. A few listened to Medivh's warning and sailed west, among them Thrall's new Horde and the expedition of Jaina Proudmoore. They found a whole continent, with ice and forest in the north and desert in the south. The Horde holds the central and eastern lands now, and the night elves keep to the northwest.",
		source = "https://warcraft.wiki.gg/wiki/Kalimdor",
	},
	[1415] = {
		name = "Eastern Kingdoms",
		short = "These lands were once part of ancient Kalimdor, until the Great Sundering split them away as three continents. Azeroth lies in the south and Lordaeron in the north.",
		full = "These lands were once part of ancient Kalimdor, until the Great Sundering split them away as three continents. Azeroth lies in the south and Lordaeron in the north. Khaz Modan sits between them, the ancestral home of the dwarves and gnomes. Its name means Mountain of Khaz, for the titan Khaz'goroth.\n\nIn the Second War the orcs overran Khaz Modan. Every dwarven mountain keep fell except Ironforge, which held. The Bleeding Hollow and Dragonmaw clans occupied the rest, and wildlife grew scarce as despoiled badlands spread. Dwarves who could flee did so, and the others hid underground and resisted.\n\nLordaeron is named for Lordain, a general of the Empire of Arathor who sacrificed himself in the Troll Wars. Humans have long held its northern, western and southern lands, and trolls the east. High elves keep their woods in the far north, and the Forsaken hold the Undercity where Lordaeron's people once lived.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Kingdoms",
	},
	[1416] = {
		name = "Alterac Mountains",
		short = "Rain falls on these peaks more often than not, and the sky stays gray under heavy cloud. Forest covers the slopes below snow on the highest ground.",
		full = "Rain falls on these peaks more often than not, and the sky stays gray under heavy cloud. Forest covers the slopes below snow on the highest ground. At the foot of the mountains, humans and high elves broke the Amani Empire in the final battle of the Troll Wars.\n\nTwo powers once stood here. Alterac was a city-state among the peaks that came to rule much of the northlands. Dalaran, the city of the Kirin Tor, stood by Lordamere Lake. Alterac fell for its treason in the Second War. Dalaran was destroyed in the Third War, and its wizards have opened the dome they raised over it while they rebuild.\n\nCrushridge ogres hold the ruins of Alterac. The Syndicate, rogues gathered by Aliden Perenolde, a prince of the fallen royal house, hold Strahnbrad and the farmland, and the two clash over the rest. Deep in the mountains, the Frostwolf orcs and the dwarves of the Stormpike Guard contest a valley of their own.",
		source = "https://warcraft.wiki.gg/wiki/Alterac_Mountains_(Classic)",
	},
	[1417] = {
		name = "Arathi Highlands",
		short = "King Thoradin built Strom, the capital of Arathor, in this dry and craggy country. Near it he raised a great wall to shield his people from the Amani trolls.",
		full = "King Thoradin built Strom, the capital of Arathor, in this dry and craggy country. Near it he raised a great wall to shield his people from the Amani trolls. The empire fell, and the Imperial Guard that stayed behind founded Stromgarde in the old city. Thoradin's Wall still runs along the northern edge, collapsed and gaping wide.\n\nStromgarde escaped the Scourge's plague, then fell to the Syndicate and the Boulderfist ogres. The remnant of its army fled the city for a small canyon to the north, now called Refuge Pointe. Prince Galen Trollbane leads the human defenders, and they, the Syndicate and the ogres still fight over the ruined city.\n\nIn the east the Horde holds Hammerfall, a camp for captured orcs that it took over and renamed for the fallen warchief Orgrim Doomhammer.",
		source = "https://warcraft.wiki.gg/wiki/Arathi_Highlands_(Classic)",
	},
	[1418] = {
		name = "Badlands",
		short = "The Badlands are cracked dry earth, strewn with boulders and cut by winding canyons, shut in by mountains on every side. Only the hardiest creatures survive here, coyotes and buzzards among them.",
		full = "The Badlands are cracked dry earth, strewn with boulders and cut by winding canyons, shut in by mountains on every side. Only the hardiest creatures survive here, coyotes and buzzards among them. In the far east, a great canyon is home to black dragon spawn.\n\nDwarf prospectors from Ironforge come to dig in the north, where the ruins of Uldaman were unearthed. The walls hold the first clues to where the dwarves came from. The Stonevault troggs, woken after thousands of years of sleep, slaughtered the explorers and now defend the city as their own. A large Dark Iron fortress stands just south of the ruins, and its dwarves war with the Dustbelcher ogres and the drakes.\n\nIn the northwest is Kargath, the only Horde outpost in Khaz Modan. Warchief Thrall sent its orcs to keep watch on their renegade Blackrock kin.",
		source = "https://warcraft.wiki.gg/wiki/Badlands_(Classic)",
	},
	[1419] = {
		name = "Blasted Lands",
		short = "The rocks of the Blasted Lands were once tan. Searing heat and wild energies turned them crimson when the Dark Portal was destroyed, and the land has stayed a desert ever since.",
		full = "The rocks of the Blasted Lands were once tan. Searing heat and wild energies turned them crimson when the Dark Portal was destroyed, and the land has stayed a desert ever since. Before that it was part of the Black Morass, a dark fen of marshland. Days are hot and nights bitterly cold. Mountains block any moisture from the north, no river runs here, and when storms roll in off the eastern sea the rain races off the packed earth and back to the water.\n\nLightning strikes the ground without end. Basilisks and scorpions have settled the waste, and ogres roam it. A remnant of the Burning Legion under Lord Kazzak has taken refuge here.\n\nA single road enters the land from the north, and the grim mages of Nethergarde Keep guard it.",
		source = "https://warcraft.wiki.gg/wiki/Blasted_Lands_(Classic)",
	},
	[1420] = {
		name = "Tirisfal Glades",
		short = "The sky over Tirisfal Glades hangs gloomy and green. The wooded hills here, on Lordaeron's northern coast, are soaked in the curse of the Lich King's plague, and the trees and brush cling to their last shreds of life.",
		full = "The sky over Tirisfal Glades hangs gloomy and green. The wooded hills here, on Lordaeron's northern coast, are soaked in the curse of the Lich King's plague, and the trees and brush cling to their last shreds of life.\n\nUnder King Terenas this was a land of quiet farms and small towns, where families lived happily for generations. It was one of the first places to fall when Prince Arthas Menethil ransacked Lordaeron. The people died, rose as slaves of the Scourge, and mass graves were dug to hold the rest. Afterward Lady Sylvanas Windrunner and her free-willed Forsaken took the glades as their own.\n\nThe Forsaken have enemies here. The Scarlet Crusade keeps several outposts, including the Scarlet Monastery, a stronghold of its faith. Scourge minions still foul the derelict farmsteads and mills. In the western hills, Forsaken paladins of Tyr's Watch hold Bandarion Keep and keep faith with the Light.",
		source = "https://warcraft.wiki.gg/wiki/Tirisfal_Glades_(Classic)",
	},
	[1421] = {
		name = "Silverpine Forest",
		short = "The pines here are tall and silver-barked, and they stand over grassy knolls. Before the Third War the Alliance kept this wood green and whole.",
		full = "The pines here are tall and silver-barked, and they stand over grassy knolls. Before the Third War the Alliance kept this wood green and whole. Then the Scourge came through, burned the crops and killed the people, and with Lordaeron fallen there was no one left to tend it. The trees went pale and sick, and ghostly mists hang between them. The forest is quiet now, except for a howling that comes and goes. Dilapidated farmsteads and abandoned mines dot the land, home to the darker things of the woods.\n\nThe Forsaken hold the north and fight a constant guerrilla war with the Rot Hide gnolls. Their claim is disputed by the wizards of Dalaran and by Scourge agents who hold some of the ruined fields. A few humans cling to the south, guarded by wizards sent from Dalaran, who also come to study the plague and the worgen curse. In the southwest, the people of Pyrewood Village turn into worgen under the moon, cursed by Archmage Arugal, who keeps to the dark towers of Shadowfang Keep.",
		source = "https://warcraft.wiki.gg/wiki/Silverpine_Forest_(Classic)",
	},
	[1422] = {
		name = "Western Plaguelands",
		short = "Before the plague, this was forested farmland east of Lordaeron's capital. Hearthglen was the seat of the regional government, and Andorhal gathered the grain of the northern provinces and sent it out across the kingdom.",
		full = "Before the plague, this was forested farmland east of Lordaeron's capital. Hearthglen was the seat of the regional government, and Andorhal gathered the grain of the northern provinces and sent it out across the kingdom.\n\nKel'Thuzad and the Cult of the Damned knew that grain was the quickest road for the plague. They infected it, and they set four massive cauldrons in the fields of the four largest farms. As Lordaeron collapsed, the forests began to die. The pines drop sickly brown needles, and their trunks swell with growths like tumors. A smoky gray mist hangs over the ground.\n\nThe land still seems to fight back, with what little it has left. The Scarlet Crusade holds Hearthglen and strikes at the Scourge from there. The one calm place is Uther's Tomb, a monument to Uther the Lightbringer.",
		source = "https://warcraft.wiki.gg/wiki/Western_Plaguelands_(Classic)",
	},
	[1423] = {
		name = "Eastern Plaguelands",
		short = "Before the plague, these lands were farms and small villages, all of them looking to Stratholme, the largest city in Lordaeron.",
		full = "Before the plague, these lands were farms and small villages, all of them looking to Stratholme, the largest city in Lordaeron. Prince Arthas Menethil came to Stratholme hunting the source of the plague and purged the city. From there he went north, returned as one of the Lich King's death knights, and killed his own father to end the kingdom of Lordaeron.\n\nThe Scourge rules here now. Stratholme is their southern capital, under the lich Kel'Thuzad, though the Scarlet Crusade holds its western districts and fights on in vain, turning outsiders away. The ground is brown and sick, the trees have swollen into giant mushrooms, and the air hangs orange with mist. Necromancers and Damned cultists prowl the roads. Amani forest trolls strike from the north. Only at Light's Hope Chapel does a small Argent Dawn camp welcome anyone willing to fight.",
		source = "https://warcraft.wiki.gg/wiki/Eastern_Plaguelands_(Classic)",
	},
	[1424] = {
		name = "Hillsbrad Foothills",
		short = "Most of Lordaeron has been twisted by the Scourge, but the Hillsbrad Foothills still look as the kingdom once did. The hills are green, the meadows fertile and the soil rich.",
		full = "Most of Lordaeron has been twisted by the Scourge, but the Hillsbrad Foothills still look as the kingdom once did. The hills are green, the meadows fertile and the soil rich. Pine trees dot the farmland, and roads cross the pastures from town to town. A river flows south from Darrowmere Lake.\n\nFor all that, this is the most blood-soaked battlefield in Azeroth. The first battle between the Alliance and the Horde in the Second War was fought here. Orc raiders struck the coastal towns, and forest trolls fought beside them against human and high elf defenders. In the Third War Thrall assembled the orcish clans, then slipped into Southshore by night and stole its ships to carry the new Horde across the sea to Kalimdor.\n\nThe Scourge wiped out the town of Tarren Mill. The Forsaken took it as their southernmost holding and now press the humans of Southshore and Hillsbrad Fields, who stand with the Alliance. Syndicate outlaws, murlocs and naga trouble both sides.",
		source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Foothills_(Classic)",
	},
	[1425] = {
		name = "The Hinterlands",
		short = "The Wildhammer dwarves hold the west of the Hinterlands, where they tame wild gryphons. The bond grew so strong that they raised an enormous monument in the likeness of a gryphon in their city.",
		full = "The Wildhammer dwarves hold the west of the Hinterlands, where they tame wild gryphons. The bond grew so strong that they raised an enormous monument in the likeness of a gryphon in their city. The forest trolls who held this land before them, remnants of the Amani Empire, call the dwarves squatters on ancestral ground and raid the aeries.\n\nThe Wildhammers knew almost nothing of the Horde when the orcs marched into the Hinterlands in the Second War. Thane Kurdran Wildhammer's gryphon riders met the invaders from the sky, hurling storm-charged hammers from their mounts and giving the columns no rest. Warchief Orgrim Doomhammer meant the attack to draw the Alliance after him while he struck Quel'Thalas. Anduin Lothar saw it, sent half his army to the elves, and fought beside Kurdran himself. Together they drove the orcs and their forest troll allies out. Kurdran pledged his kingdom to the Alliance.\n\nOf the three troll tribes here, only the Revantusk have taken the Horde's side.",
		source = "https://warcraft.wiki.gg/wiki/Hinterlands_(Classic)",
	},
	[1426] = {
		name = "Dun Morogh",
		short = "Snow lies deep across Dun Morogh, and its mountains are the highest in the Eastern Kingdoms. Their glaciers feed the rivers that water the green fields of Khaz Modan, and their peaks give the dwarves ore without end.",
		full = "Snow lies deep across Dun Morogh, and its mountains are the highest in the Eastern Kingdoms. Their glaciers feed the rivers that water the green fields of Khaz Modan, and their peaks give the dwarves ore without end. Mountains close the land in on every side, and dwarven troops watch the few passes in.\n\nIce trolls of the Frostmane tribe once ruled here, until dwarven armies broke their empire and drove them back into the hills. Dwarves and gnomes became close friends. The dwarves helped the gnomes raise Gnomeregan, and the gnomes shared their knowledge of machines. When the orcs invaded Khaz Modan in the Second War, both peoples joined the Alliance, and between dwarven strength and gnomish invention the orcs never took either capital.\n\nNow Gnomeregan has fallen, and its survivors shelter in Ironforge. Troggs are turning up all over the region. The Frostmane see that Ironforge's armies are busy with the troggs and the Alliance's wars, and they raid the dwarves more often.",
		source = "https://warcraft.wiki.gg/wiki/Dun_Morogh_(Classic)",
	},
	[1427] = {
		name = "Searing Gorge",
		short = "More than two hundred years ago the ground here was torn open. Before that the land was part of the Redridge Mountains.",
		full = "More than two hundred years ago the ground here was torn open. Before that the land was part of the Redridge Mountains. Sorcerer-Thane Thaurissan of the Dark Iron dwarves needed something to turn the War of the Three Hammers his way. He and seven of his most trusted dwarves called on the ancient powers sleeping beneath the world, and what answered was the Firelord Ragnaros, more terrible than any nightmare they had imagined. Blackrock Mountain burst up out of the ridge, the Dark Iron capital of Thaurissan fell to rubble, and the valley to the north became a blackened rift, the Searing Gorge.\n\nThe Dark Irons wanted land for their works, and the gorge had few people and few soldiers, so a large Dark Iron force overran the dwarven garrisons and put slaves to work digging out the middle of the valley. War golems and elementals walk the gorge beside them.\n\nThe Thorium Brotherhood, Dark Iron dwarves who broke from the clan, holds its own town in the north of the gorge.",
		source = "https://warcraft.wiki.gg/wiki/Searing_Gorge_(Classic)",
	},
	[1428] = {
		name = "Burning Steppes",
		short = "The sky over the Burning Steppes glows red, lit by eruptions from Blackrock Mountain. Rivers of lava cross the craggy foothills, the earth is charred, and the air stays hot and dry.",
		full = "The sky over the Burning Steppes glows red, lit by eruptions from Blackrock Mountain. Rivers of lava cross the craggy foothills, the earth is charred, and the air stays hot and dry. The road here, the only land passage from Stormwind to Khaz Modan and Lordaeron, is well traveled and dangerous, and Stormwind has all but abandoned it.\n\nThe land was once part of the Redridge Mountains. In the War of the Three Hammers the Dark Iron Sorcerer-Thane, Thaurissan, tried to summon elemental servants and called up Ragnaros the Firelord instead. The mountains melted, and a volcano rose where he came through. The surviving Dark Irons became his puppets.\n\nOrcs settled here after the Second War. The Blackrock orcs keep one of the few lasting orc settlements in Azeroth and do not honor Thrall's truce with the Alliance. Firegut ogres roam the countryside. Black dragons under Nefarian hold the upper levels of Blackrock Spire, and Dark Iron dwarves hold its depths, where rumor says Ragnaros still broods.",
		source = "https://warcraft.wiki.gg/wiki/Burning_Steppes_(Classic)",
	},
	[1429] = {
		name = "Elwynn Forest",
		short = "In the First War, thousands of orcs marched through Elwynn Forest and closed around Stormwind, leaving the sea as the only way out.",
		full = "In the First War, thousands of orcs marched through Elwynn Forest and closed around Stormwind, leaving the sea as the only way out. Anduin Lothar led the Knights of Stormwind in a charge through the trees and caught the orcish rearguard by surprise. The orcs fled, but the relief did not last. Fire swept much of the forest, and in the second siege Stormwind fell. Lothar led the survivors onto boats bound for Lordaeron.\n\nThe trees have grown back since, hardwoods and lush glades between rushing rivers and lakes, and frequent rain keeps the farmland rich. Loggers, farmers, fishers and miners work it, and Stormwind could not last long without what they send. Here and there an orcish catapult still lies broken and rotting.\n\nThe stonemasons spent years rebuilding Stormwind and were never paid. When Guildmaster Edwin VanCleef demanded what was owed, the nobles ordered the guild disbanded. Riots followed, and out of them came the Defias Brotherhood. Its bandits keep holdings across the forest.",
		source = "https://warcraft.wiki.gg/wiki/Elwynn_Forest_(Classic)",
	},
	[1430] = {
		name = "Deadwind Pass",
		short = "The Ivory Tower of Karazhan stands at the heart of the pass, which cuts through the mountains of central Azeroth and joins Duskwood to the Swamp of Sorrows.",
		full = "The Ivory Tower of Karazhan stands at the heart of the pass, which cuts through the mountains of central Azeroth and joins Duskwood to the Swamp of Sorrows. A score of years ago it was counted part of the Redridge Mountains. It was the home of the dark wizard Medivh, who opened the Dark Portal for the orcs and was hunted down and killed in the First War. The tower has stood abandoned since, and its evil magic still leaks into the land.\n\nNothing grows here. The trees are petrified and leafless, and a foul wind keens through the jagged canyon that gives the pass its name. Ogres, demons and undead roam the interior, along with a few human gypsies. Carrion birds are the only wildlife.\n\nNobles from Darkshire came to look into the blight, and none who entered the tower came out again. Travelers say a new power has claimed it, and that the ogres and demons answer to it. The Dark Riders, a mysterious band seen in Duskwood, are known to come from this pass.",
		source = "https://warcraft.wiki.gg/wiki/Deadwind_Pass_(Classic)",
	},
	[1431] = {
		name = "Duskwood",
		short = "Duskwood was once the southern part of Elwynn Forest, a fiefdom of Stormwind called Brightwood. Two sizable towns stood among its farms.",
		full = "Duskwood was once the southern part of Elwynn Forest, a fiefdom of Stormwind called Brightwood. Two sizable towns stood among its farms. Now a black fog hangs beneath the trees, the trunks have grown gnarled, and the night does not lift.\n\nWorgen came with the fog. The dead walk out of the graveyards, and ogres have pushed in from Deadwind Pass. Stormwind is far away and long ago abandoned the forest, but the people who remain cling to their holdings. Their militia, the Night Watch, patrols the roads and guards Darkshire against skeletal warriors, ghouls, worgen and Defias men.\n\nAt its heart lies an ancient volcano crater, long dead and now full of life, with a twilight gentler than the dark outside. Elsewhere lie abandoned farmsteads and Raven Hill Cemetery, which holds the graves of everyone killed by beasts and undead since the darkness fell.",
		source = "https://warcraft.wiki.gg/wiki/Duskwood_(Classic)",
	},
	[1432] = {
		name = "Loch Modan",
		short = "Gray mountains rise on every side of Loch Modan, their hills lightly wooded with pine and birch. The Stonewrought Dam holds the loch in place, a work of dwarven engineering that has no equal on Azeroth.",
		full = "Gray mountains rise on every side of Loch Modan, their hills lightly wooded with pine and birch. The Stonewrought Dam holds the loch in place, a work of dwarven engineering that has no equal on Azeroth.\n\nQuiet as it looks, the loch has seen war. In the Second War the orcs of the Horde overran this land and made a stand against the defenders of the Alliance. The dwarves of Ironforge held out, and when the war ended they reclaimed the country. Broken catapults and ballistae still lie on the bottom of the loch and on its islands, plain evidence of that fighting.\n\nPeace has not returned. The dwarven digs broke open caves under the ground, and the troggs they unearthed have settled in the mountains. They build crude camps and caves from which to strike at passing travelers. Hostile kobolds, wild beasts and the ogres of the northeast add to the danger.",
		source = "https://warcraft.wiki.gg/wiki/Loch_Modan_(Classic)",
	},
	[1433] = {
		name = "Redridge Mountains",
		short = "Elms rise over fast rivers in the Redridge Mountains, and the land climbs steadily toward the peaks. The range lies east of Elwynn Forest and south of the Burning Steppes.",
		full = "Elms rise over fast rivers in the Redridge Mountains, and the land climbs steadily toward the peaks. The range lies east of Elwynn Forest and south of the Burning Steppes. These hills lie under Stormwind's protection, though since the Second War they have been independent in name. The people are calm and content. They send Stormwind timber from the woods, fish from the lake and crops from the fields, and Redridge is one of the last peaceful regions in Azeroth.\n\nThe peace is imperfect. A force of Blackrock orcs came down from the Burning Steppes and holds Stonewatch Keep. Gnolls and more Blackrock orcs press on the town of Lakeshire from the surrounding hills. The road from the crossroads at Three Corners toward the keep is held by dragon whelps, gnolls, murlocs and wild beasts.\n\nThe surface of Lake Everstill looks calm. Murlocs live beneath it, and people still talk of a sea monster in the deep water.",
		source = "https://warcraft.wiki.gg/wiki/Redridge_Mountains_(Classic)",
	},
	[1434] = {
		name = "Stranglethorn Vale",
		short = "For ages the jungle trolls of the Gurubashi ruled this land, and their stone cities lay scattered across it. The empire turned cruel.",
		full = "For ages the jungle trolls of the Gurubashi ruled this land, and their stone cities lay scattered across it. The empire turned cruel. It sacrificed trolls of other tribes to Hakkar the Soulflayer, a blood god, and a long civil war split the tribes apart for good. The Darkspear went their own way, and those who stayed in the vale have fought one another ever since.\n\nThe cities fell and the jungle closed over them. The Bloodscalp hold the northwest and the Skullsplitters the east, each tribe living among the ruins. Zul'Gurub, once the capital, sits in a valley in the northeast. Naga hunt along the coast, and the strangle-thorns that name the vale tangle every path inland.\n\nOutsiders keep coming. Goblins run a harbor on the southern shore, and pirates make it their port. In the north, Colonel Conrad Kurzen's expedition has raised a compound among the trees, where his men are at war with one another. The trolls watch all of it, and their wish to purge the land of foreigners grows.",
		source = "https://warcraft.wiki.gg/wiki/Stranglethorn_Vale_(Classic)",
	},
	[1435] = {
		name = "Swamp of Sorrows",
		short = "Once the northern half of a vast marshland called the Black Morass, the Swamp of Sorrows saw the Dark Portal open in the southern half.",
		full = "Once the northern half of a vast marshland called the Black Morass, the Swamp of Sorrows saw the Dark Portal open in the southern half. The orcs came through and raised two settlements and an outpost in the mire. When the portal collapsed in the Second War, the southern half became the Blasted Lands, and the northern half is now the Swamp of Sorrows.\n\nThis is a stagnant land of sucking bogs and weeping trees. Seawater seeps into the fen, so the pools are brackish and full of crocolisks, and salt crusts the fallen logs and rocks. Bog beasts wade through the interior, and jaguars hunt along the banks, and the one road rises only inches above the water.\n\nSome draenei came through the Dark Portal in search of a new life and settled here. Homesickness drove most of them mad, and they attack all on sight. Far from Stormwind, the Horde has planted a colony of its own. Green dragons patrol the marsh at the command of Ysera the Dreamer, guarding a ruined troll temple beneath its largest bog.",
		source = "https://warcraft.wiki.gg/wiki/Swamp_of_Sorrows_(Classic)",
	},
	[1436] = {
		name = "Westfall",
		short = "The wind crosses Westfall's fields with nothing to stop it. This was the breadbasket of Stormwind, rolling pasture and farmland, and now the grass is yellow and thin and carrion birds fill the fields.",
		full = "The wind crosses Westfall's fields with nothing to stop it. This was the breadbasket of Stormwind, rolling pasture and farmland, and now the grass is yellow and thin and carrion birds fill the fields.\n\nThe Stonemasons Guild rebuilt Stormwind after the Second War and was never paid for it. Its guildmaster, Edwin VanCleef, led the masons out into the countryside, and there they became the Defias Brotherhood. The farmers were still shaken from the orc raids and put up little resistance. The Brotherhood drove many of them off and hired Riverpaw gnolls to hold the land. Its men burned the fields and salted the earth, and once goblins joined its ranks, the Brotherhood armed itself with harvest golems that hunt anyone who walks the fallow rows alone.\n\nStormwind, short of gold and soldiers, leaves the region to itself. Gryan Stoutmantle founded the People's Militia, a volunteer force that keeps a last stronghold here against the Brotherhood.",
		source = "https://warcraft.wiki.gg/wiki/Westfall_(Classic)",
	},
	[1437] = {
		name = "Wetlands",
		short = "Mist hangs low over the Wetlands, and the sky is a flat gray from one end of the country to the other.",
		full = "Mist hangs low over the Wetlands, and the sky is a flat gray from one end of the country to the other. Small rivers, lakes and ponds run through the ground, mountains close it in on three sides, and the ocean lies open to the west. Dwarven strongholds once stood all across this land. War has left them as rubble, and murlocs, wild beasts and renegade orcs hold it now.\n\nIn the Second War the Dragonmaw clan took the fortress of Grim Batol in the mountains to the east. The orcs and their dragons ate the wildlife thin, and the plants suffered along with it.\n\nThe Dragonmaw lost their hold when the red dragons they had enslaved broke free and burned their bases and catapults. The survivors fled south into the mountains, where they still live. Menethil Harbor, on a small island in Baradin Bay, is the Alliance's only foothold in the Wetlands.",
		source = "https://warcraft.wiki.gg/wiki/Wetlands_(Classic)",
	},
	[1438] = {
		name = "Teldrassil",
		short = "After the Third War, Malfurion Stormrage vanished into the Emerald Dream, and the archdruid Fandral Staghelm took over the leadership of the night elf druids.",
		full = "After the Third War, Malfurion Stormrage vanished into the Emerald Dream, and the archdruid Fandral Staghelm took over the leadership of the night elf druids. He told the Circle of Ancients that the time had come to grow a new World Tree and win back the immortality the night elves had lost. Their joined powers raised an immense tree out of the Veiled Sea, and they named it Teldrassil, crown of the earth.\n\nThe night elves made their home in its boughs, where a twilit forest of mighty trees, streams and lakes covers the great limbs, with Darnassus on the western side. But Nozdormu called the wish arrogant and refused to bless the tree. Its growth is flawed, and the immortality never came.\n\nNow a sinister presence has settled over the land. Furbolgs and grell have gone mad, and satyrs have appeared among the trees. The great turtles and threshers of the surrounding sea flee to beach themselves and die on the shores of Darkshore. The source of the corruption is still a mystery.",
		source = "https://warcraft.wiki.gg/wiki/Teldrassil_(Classic)",
	},
	[1439] = {
		name = "Darkshore",
		short = "The name comes from the mist. A gray haze lies over this coast most days, and rain and wind scour its rocky beaches.",
		full = "The name comes from the mist. A gray haze lies over this coast most days, and rain and wind scour its rocky beaches.\n\nTen thousand years ago the land lay farther inland, and the night elves raised great cities here, Ameth'Aran and Bashal'Aran among them. They fell when the first Well of Eternity was shattered, and the Great Sundering cut a new coastline through the region. Their ruins still stand on the cliffs, and stories say that murlocs and naga are slowly taking them over.\n\nThe few night elves who lived here left during the Third War. After it, a small number came back to revive the port, and they cleared away the ruins they could not restore. Fandral Staghelm also led druids onto this shore, and from it they planted Teldrassil.\n\nThe mountains to the east keep out most of the taint of Felwood, but the rivers carry it down anyway. It turns the land gray and poisons the wildlife, and the furbolgs it reaches fall into a rage that does not leave them.",
		source = "https://warcraft.wiki.gg/wiki/Darkshore_(Classic)",
	},
	[1440] = {
		name = "Ashenvale",
		short = "Rain falls almost without pause in Ashenvale, but the trees are so old and thick that only trickles reach the ground. The night elves hunted these woods after the Great Sundering and never built a city in them.",
		full = "Rain falls almost without pause in Ashenvale, but the trees are so old and thick that only trickles reach the ground. The night elves hunted these woods after the Great Sundering and never built a city in them. The Sentinels and the ancients, living trees that act as wardens, guard the forest and strike at anyone who cuts a live tree.\n\nThe Horde came in the Third War. Goblins under Neeloc Greedyfingers began felling the trees, and the Warsong clan followed. Cenarius came to restore the cut trees, and Grommash Hellscream, tricked by the masters of the Burning Legion, killed the demigod. Then Archimonde's infernals fell burning from the sky, and undead and demons marched through the forest toward Mount Hyjal.\n\nNow the night elves hold Astranaar and their other refuges in the west. The Horde holds the east from Splintertree Post and cuts timber at the Warsong lumber camps. Demons of the Legion still linger in the forest, and satyrs have taken old elven ruins for their own.",
		source = "https://warcraft.wiki.gg/wiki/Ashenvale_(Classic)",
	},
	[1441] = {
		name = "Thousand Needles",
		short = "It is thought that a river once cut this canyon, leaving tall columns of sandstone standing in it, with green forest along its banks.",
		full = "It is thought that a river once cut this canyon, leaving tall columns of sandstone standing in it, with green forest along its banks. Then the Sundering tore the world apart. The river changed course, the trees died, and the soil turned to orange dust. The lake in the east dried into a vast salt flat that lies below the level of the sea. Despite the barren ground, the sunrise seen from Freewind Post or from the mesas around Darkcloud Pinnacle can be spectacular.\n\nDozens of the stone columns still rise from the canyon floor like a forest. Bridges cross the tops of many of them, so a traveler can get over the canyon without meeting the centaur war bands that patrol below.\n\nThe canyons have long been tauren ground. To keep clear of the centaur tribes that nearly wiped them out, the tauren live on the tips of the high mesas. Now, with the help of the Horde, they are fighting back against the centaur and against the fanatical Grimtotem tribe.",
		source = "https://warcraft.wiki.gg/wiki/Thousand_Needles_(Classic)",
	},
	[1442] = {
		name = "Stonetalon Mountains",
		short = "The Stonetalon Mountains keep their holiest ground on the largest peak in the range. Night elves tend a barrow and a glade at the top and commune there with the spirits of nature.",
		full = "The Stonetalon Mountains keep their holiest ground on the largest peak in the range. Night elves tend a barrow and a glade at the top and commune there with the spirits of nature. The tauren hold the peak sacred too, because the immortal Oracle once lived here and watched the strands of fate as the Earth Mother wove them.\n\nElune blessed a Fountain of Health in these mountains in ancient times. During the Third War, harpies captured the wyverns that nested nearby and fouled the fountain's water. Thrall came against them with Cairne Bloodhoof and his tauren. They broke a band of centaur to win a Glyph of Purification and cleansed the fountain with it.\n\nLower down, the land has been stripped. Goblins of the Venture Company have cut almost every tree in Windshear Crag, filled the air with soot, and spoiled the water with oil and waste, to the fury of the orcs and tauren. The mountain spirits cried out against it, loud enough that the shaman as far off as Orgrimmar heard.",
		source = "https://warcraft.wiki.gg/wiki/Stonetalon_Mountains_(Classic)",
	},
	[1443] = {
		name = "Desolace",
		short = "Desolace is a gray, rocky waste littered with bones, under black skies and constant wind. The skulls of ancient kodo stare from half-buried graves, and the husks of long-dead trees are all that is left of a green past.",
		full = "Desolace is a gray, rocky waste littered with bones, under black skies and constant wind. The skulls of ancient kodo stare from half-buried graves, and the husks of long-dead trees are all that is left of a green past. Only the western coast is still lush.\n\nLegend says the centaur came from a union between a son of the demigod Cenarius, Zaetar, and a princess of the earth elementals, Theradras, and that the first khans murdered their father for shame of their misshapen form. Their race was born in the western canyons, from Maraudon. Once the night elves stopped holding them in check, the centaur turned on the tauren and at last drove them out of Desolace.\n\nNow four tribes of centaur, each under its own khan, fight one another as fiercely as they fight outsiders. The Horde and the Alliance have both set up camps here, and the Burning Blade cult has opened portals to bring demons into the land.",
		source = "https://warcraft.wiki.gg/wiki/Desolace_(Classic)",
	},
	[1444] = {
		name = "Feralas",
		short = "Where the land around it is barren, Feralas is a jungle of huge, ancient trees. The night elves once spread their power through this forest, and their ruins lie everywhere, overgrown by roots and vines.",
		full = "Where the land around it is barren, Feralas is a jungle of huge, ancient trees. The night elves once spread their power through this forest, and their ruins lie everywhere, overgrown by roots and vines. The greatest is the city now called Dire Maul.\n\nThe Gordunni ogres have made themselves masters of the ruins and of much of the forest, and they have defiled what they hold and left their taint on the land. Raiding parties burn villages and ambush travelers in the southern woods. The Horde fears the clan's growth.\n\nGrimtotem tauren live scattered through the woods, hunted by Horde agents on Belgrom's orders. Naga crowd the islands off the western coast, and silithid hives have lately been found in the forest. One of the four Great Trees that open onto the Emerald Dream grows here, guarded by the green dragons.",
		source = "https://warcraft.wiki.gg/wiki/Feralas_(Classic)",
	},
	[1445] = {
		name = "Dustwallow Marsh",
		short = "Dustwallow Marsh was once a high plain of tall grass, grazed by great herds. The Sundering smashed it down into a valley, and water bled up from underground and has kept it wet ever since.",
		full = "Dustwallow Marsh was once a high plain of tall grass, grazed by great herds. The Sundering smashed it down into a valley, and water bled up from underground and has kept it wet ever since. Crocolisks, raptors and spiders wait in every pool and bush. In the south, black dragons nest in such numbers that the land is called the Wyrmbog.\n\nWild beasts had the marsh to themselves until the Third War. After the battle at Mount Hyjal, Lady Jaina Proudmoore led her people to the eastern shore and raised Theramore on a rocky island. Her father, Grand Admiral Daelin Proudmoore, brought the Kul Tiran fleet against the Horde, and the marsh became a battleground.\n\nNeither the Horde nor the Alliance holds much of it now. A few towers and checkpoints stand along the road to the Barrens, and Theramore's garrison is thinning as soldiers desert, for reasons nobody can explain. The only Horde foothold is Brackenwall Village in the northwest, where the Stonemaul ogres live under Overlord Mok'Morokk.",
		source = "https://warcraft.wiki.gg/wiki/Dustwallow_Marsh_(Classic)",
	},
	[1446] = {
		name = "Tanaris",
		short = "Nozdormu, the dragon of time, is said to have made this land his home since before anyone counted years. The heat and the miles of empty sand suited him.",
		full = "Nozdormu, the dragon of time, is said to have made this land his home since before anyone counted years. The heat and the miles of empty sand suited him. Tanaris has been an endless sea of sand for aeons.\n\nThe land is rolling dunes under a cloudless sky, with sandstorms that come up fast. The south is rougher, with mountains over cave networks that run deep and are barely explored. Hyenas, scorpids, basilisks and silithid are common out in the sand, and drakes sometimes ride the hot air overhead. The silithid have been building hives in the remote regions for a long time. The titans left a holding here too, the ancient city of Uldum.\n\nThe goblins of the Steamwheedle Cartel built Gadgetzan and Steamwheedle Port in this desert. It is as close to their homeland as they can get on the continents.",
		source = "https://warcraft.wiki.gg/wiki/Tanaris_(Classic)",
	},
	[1447] = {
		name = "Azshara",
		short = "Autumn never leaves Azshara. The trees along the coast burn orange and red, and past them great cliffs drop to ivory beaches and a shallow sea broken by spires of jagged rock.",
		full = "Autumn never leaves Azshara. The trees along the coast burn orange and red, and past them great cliffs drop to ivory beaches and a shallow sea broken by spires of jagged rock.\n\nThis coast was once part of Zin-Azshari, the night elf capital. When the demons were cast out of the world, the Great Sundering tore the land apart and the sea poured in. Most of the city drowned. A few ragged buildings still perch on the cliffs above ruins among the coral. The night elves who lived through it named the broken coast for Azshara, their queen, driven mad by demonic influence, and they call it cursed.\n\nIn the Third War, Illidan Stormrage came through with his naga and satyrs and wrecked the elven harbors so that no one could follow him. Maiev Shadowsong and her Watchers followed his trail and had to put down the suffering creatures he left behind. Some night elves say demons still lurk beneath the water. Others say the queen survived the drowning and was changed into a hideous creature of the sea.",
		source = "https://warcraft.wiki.gg/wiki/Azshara_(Classic)",
	},
	[1448] = {
		name = "Felwood",
		short = "Felwood was once the northern woods of Ashenvale, tended by the night elves and watched over by Cenarius. Then the Burning Legion pressed toward Mount Hyjal.",
		full = "Felwood was once the northern woods of Ashenvale, tended by the night elves and watched over by Cenarius. Then the Burning Legion pressed toward Mount Hyjal. Archimonde ordered the forest corrupted to weaken the night elves who defended it, and the dreadlord Tichondrius carried out the order with the Skull of Gul'dan, a warlock relic. Illidan Stormrage braved the forest, defeated Tichondrius and took the skull. His brother Malfurion banished him for using demonic power, but the taint stayed in the land.\n\nNothing grows in the meadows now. The ancients that once guarded the woods roam blindly, their twisted limbs bleeding fel poison, and they turn their worst fury on anything that looks like an elf. Plant eaters refuse the cursed vegetation, so the beasts feed on each other and are mad with rage. Furbolgs ruined by the corruption wander the trees, and satyrs gather at tainted moonwells. The night elves are ashamed that they failed this forest, and they have not stopped trying to heal it.",
		source = "https://warcraft.wiki.gg/wiki/Felwood_(Classic)",
	},
	[1449] = {
		name = "Un'Goro Crater",
		short = "Three deserts press in around Un'Goro Crater and cut it off almost entirely from the rest of the world. Even so, a thick jungle of exotic plants and stranger beasts fills it.",
		full = "Three deserts press in around Un'Goro Crater and cut it off almost entirely from the rest of the world. Even so, a thick jungle of exotic plants and stranger beasts fills it. Peaceful earth elementals walk among raging devilsaurs. A volcano rises at the center, where fire elementals prowl, and strange crystals dot the ground. Few know their purpose, though some of the scientists camped here study them.\n\nPylons stand on the ridges above, and close examination has not explained them. The Qiraji call this crater the God Lands, and it is ancient past all living memory.",
		source = "https://warcraft.wiki.gg/wiki/Un'Goro_Crater_(Classic)",
	},
	[1450] = {
		name = "Moonglade",
		short = "Moonglade lies cradled in a ring of mountains, a hidden vale of hills and old forest that corruption has never touched. Countless mounds rise among the trees, and beneath them lie the sanctums of druids past.",
		full = "Moonglade lies cradled in a ring of mountains, a hidden vale of hills and old forest that corruption has never touched. Countless mounds rise among the trees, and beneath them lie the sanctums of druids past.\n\nCenarius once dwelled here. In the War of the Ancients, as the Burning Legion's numbers swelled, Malfurion Stormrage saw that the night elves could not win alone. He brought Tyrande Whisperwind and his brother Illidan into the sacred quiet of the valley to beg Cenarius for aid. The demigod answered. After the Great Sundering, the keepers of the grove and the dryads who had sheltered here went out into the world.\n\nSome years after the Third War, Moonglade was opened to all the druid races, and Keeper Remulos became its guardian. Tauren and night elves live side by side, and the Moonglade Wardens allow no quarrels between them. The mad demigod Omen sleeps in the depths of the central lake and stirs each year around the Lunar Festival.",
		source = "https://warcraft.wiki.gg/wiki/Moonglade",
	},
	[1451] = {
		name = "Silithus",
		short = "Sand and broken rock cover the southwestern corner of Kalimdor, and the only things that rise from the waste are the huge hives of the silithid.",
		full = "Sand and broken rock cover the southwestern corner of Kalimdor, and the only things that rise from the waste are the huge hives of the silithid.\n\nA part of the old Aqiri empire lies here, the land called Ahn'Qiraj. It stands uninhabited now, and its central temple is sealed. At the end of the War of the Shifting Sands the night elves and the bronze dragons shut the Qiraji behind the Scarab Wall, and the desert has held that prison for thousands of years. The Qiraji's servants, the silithid, were not sealed in. They have multiplied and spread across southern Kalimdor.\n\nThe Cenarion Circle keeps a constant watch from Cenarion Hold. The bronze dragonflight, Nozdormu's brood, has returned to the desert for the first time in ten thousand years.",
		source = "https://warcraft.wiki.gg/wiki/Silithus_(Classic)",
	},
	[1452] = {
		name = "Winterspring",
		short = "Above Moonglade the mountain climbs through a thick bank of white cloud, and beyond it lies Winterspring. The air is crisp and clean up here.",
		full = "Above Moonglade the mountain climbs through a thick bank of white cloud, and beyond it lies Winterspring. The air is crisp and clean up here. Snow covers the ground, and when it is not falling the sun often shines.\n\nThe trees were bent into odd shapes during the Battle of Mount Hyjal, and roots of the World Tree stand exposed, towering overhead like great oak arches. Thousands of years ago, after the Great Sundering, night elves came to this valley to begin again. An older quarrel runs through it, between malevolent blue dragons and the white frostsaber cats that prowl the slopes.\n\nConflict still shakes the valley. The blue dragonflight's forces, among them General Colbatann, clash with the night elves, who want them gone from the slopes of Mount Hyjal. Demons have taken over the southern parts of the land completely. Goblins hold the trading town of Everlook.",
		source = "https://warcraft.wiki.gg/wiki/Winterspring_(Classic)",
	},
	[1453] = {
		name = "Stormwind City",
		short = "Orcs of the Horde burned Stormwind in the First War. After the Second War its people came home to the ruins, and the Stonemasons' Guild rebuilt the city in white stone.",
		full = "Orcs of the Horde burned Stormwind in the First War. After the Second War its people came home to the ruins, and the Stonemasons' Guild rebuilt the city in white stone. The work cost more than the crown could pay. The nobles had run up a huge debt, spreading the army through Elwynn and into Stranglethorn, and the guild's fees went unpaid.\n\nWhen Guildmaster Edwin VanCleef demanded them, the House of Nobles ordered the guild disbanded. Riots followed, and in them Queen Tiffin Wrynn was killed by accident. King Varian Wrynn vowed to punish those responsible and dealt with the rioters harshly. The stonemasons fled the city and hid in Westfall, where they became the Defias Brotherhood.\n\nKing Varian has since vanished under suspicious circumstances. His young son, Prince Anduin, was given the crown so that order could be kept, and Highlord Bolvar Fordragon serves as regent and commands the kingdom's forces.",
		source = "https://warcraft.wiki.gg/wiki/Stormwind_City",
	},
	[1454] = {
		name = "Orgrimmar",
		short = "Soon after the Battle of Mount Hyjal, Warchief Thrall led his people to a bare stretch of Kalimdor's coast.",
		full = "Soon after the Battle of Mount Hyjal, Warchief Thrall led his people to a bare stretch of Kalimdor's coast. He named the land Durotar for his late father, Durotan, and the fortress he raised there he named Orgrimmar, for his friend and mentor Orgrim Doomhammer. It was built fast and built to hold. Stout walls, massive gates and tall towers guard it, and the mountains at its back were carved into parts of the fortress itself.\n\nThe curse on the orcs had ended, and the Horde was no longer a juggernaut bent on war. Thrall's people wanted to survive and prosper. Goblins, tauren and Darkspear trolls helped raise the city, and so did the Mok'Nathal Rexxar. Centaur, harpies and quilboar gave the builders trouble, but the city thrived.\n\nOrcs and Darkspear trolls live here now, with tauren and the Forsaken the Horde has lately accepted. Old shaman pass their knowledge to the Horde's newest leaders, and razor-winds sweep the valleys hard enough to tear the roofs from poorly built houses.",
		source = "https://warcraft.wiki.gg/wiki/Orgrimmar",
	},
	[1455] = {
		name = "Ironforge",
		short = "The first dwarves walked out of Uldaman and went west to the mountains of Dun Morogh.",
		full = "The first dwarves walked out of Uldaman and went west to the mountains of Dun Morogh. They dug into the tallest peak, raised an altar to Khaz'goroth, the titan they called their father, and built the Great Forge beneath it. A city grew around the fire and took its name from the forge.\n\nIronforge is a cavern cut into the mountain, its halls laid out in rings around the Great Forge at its heart, with smaller levels deeper underground. Falls of molten rock run down the walls, shops are built into the stone, and hearths roar in every inn. The feel of the place is bustling, rowdy and industrial, yet cozy.\n\nWhen the Horde swept over Khaz Modan in the Second War, one dwarven stronghold after another fell, and the survivors of each fled to Ironforge. Kilrogg Deadeye and his Bleeding Hollow clan fought the dwarves for months and could not take the city. King Magni Bronzebeard rules here now, and the gnomes driven out of Gnomeregan have been given a quarter of their own, Tinker Town.",
		source = "https://warcraft.wiki.gg/wiki/Ironforge",
	},
	[1456] = {
		name = "Thunder Bluff",
		short = "For countless generations the tauren wandered, and the centaur hunted them across the plains. Then Warchief Thrall and the Horde came to Kalimdor.",
		full = "For countless generations the tauren wandered, and the centaur hunted them across the plains. Then Warchief Thrall and the Horde came to Kalimdor. With their help Cairne Bloodhoof and his tribe drove the centaur back and took the grasslands of Mulgore. For the first time in hundreds of years the tauren had land of their own.\n\nCairne built his refuge on a row of windswept mesas, high above the grass. Elevators of rope and wood, an invention unique to the tauren, lift people from the foot of the bluffs, and long bridges of the same make cross the gaps between the mesas. Tents, longhouses and painted totems stand on every summit.\n\nTauren of every tribe are welcome here, and the scattered tribes have come together under Cairne's rule. A few disagree with him about the direction the new nation should take. All of them agree that no one is wiser than he is.",
		source = "https://warcraft.wiki.gg/wiki/Thunder_Bluff",
	},
	[1457] = {
		name = "Darnassus",
		short = "Immortality ended for the night elves after the Third War, and many could not bear aging, disease and frailty.",
		full = "Immortality ended for the night elves after the Third War, and many could not bear aging, disease and frailty. A number of druids set out to win it back by planting a great tree that would join their spirits to the eternal world again. With Malfurion Stormrage missing, Fandral Staghelm, who led them, became Archdruid. The tree, Teldrassil, grew above the clouds off the stormy coast of northern Kalimdor. In its twilight boughs the city of Darnassus took root, built to honor the survival of the night elves.\n\nThe city stands around a lake and is open to the sky. Graceful bridges cross the water and keep the buildings far apart, so nothing feels crowded. Lodges of worked wood and tended groves line the shores, and fallen leaves cover the paths. The Temple of the Moon rises above the trees like a beacon. High Priestess Tyrande Whisperwind rules from it, and the Sentinels keep watch over the city. It remains a tranquil refuge, and a monument to a people learning to live with mortality.",
		source = "https://warcraft.wiki.gg/wiki/Darnassus",
	},
	[1458] = {
		name = "Undercity",
		short = "The Undercity was old before the Forsaken claimed it.",
		full = "The Undercity was old before the Forsaken claimed it. Far beneath the palace of Lordaeron lay the ancient crypts and catacombs of its royal dead, along with the city's dungeons and sewers, and the poorest of Lordaeron's people lived there among the prisoners and the dead.\n\nArthas Menethil meant the Undercity to be the Scourge's seat of power in Lordaeron, but the Lich King called him away before it was built. As the Lich King's grip loosened, Lady Sylvanas Windrunner led a group of free-willed undead out of the Scourge. She lured Arthas into a trap, though he escaped. When the fighting over Lordaeron was done, she named her followers the Forsaken and claimed the ruined capital as their own.\n\nThe Forsaken spent years finishing the maze of catacombs the Scourge had begun. Rivers of poisonous sludge run through every avenue, and the fumes are almost unbearable for the living members of the Horde. For Sylvanas and her cursed people it is a refuge in a world that fears and hunts their kind.",
		source = "https://warcraft.wiki.gg/wiki/Undercity",
	},
	[2482] = {
		name = "Mount Hyjal",
		short = "Mount Hyjal was a sanctuary of the Wild Gods, watched over by Keeper Freya. The night elves held it sacred, and Queen Azshara kept her empire from touching it.",
		full = "Mount Hyjal was a sanctuary of the Wild Gods, watched over by Keeper Freya. The night elves held it sacred, and Queen Azshara kept her empire from touching it. The mountain held when the world broke apart, and the night elf survivors gathered on it to rebuild their society, without arcane magic this time.\n\nIllidan Stormrage made a second Well of Eternity at the top of the mountain. The night elves planted the world tree Nordrassil over it, and three dragon aspects, Alexstrasza, Nozdormu and Ysera, blessed it. It healed the land and kept the night elves free of age and disease.\n\nIn the Third War the demon Archimonde led the Burning Legion up the slopes, and orcs, humans and night elves stood against him together. The wisps of Hyjal gathered in Nordrassil and the blast destroyed Archimonde, but it stripped the tree of its enchantments, and the night elves lost their immortality. Since then the mountain has been sealed behind dense growth while Nordrassil slowly recovers.",
		source = "",
	},
	[2521] = {
		name = "Zephras Isle",
		short = "Nearly ten thousand years ago a masked rebel called the Shal'nan led a rising against Prince Tortheldrin in the Highborne city of Eldre'Thalas.",
		full = "Nearly ten thousand years ago a masked rebel called the Shal'nan led a rising against Prince Tortheldrin in the Highborne city of Eldre'Thalas. The rebels fled west by sea and found a land ruled by wind spirits. The spirits struck a bargain with them, lifted part of that land into the sky as Zephras Isle and anchored it in Skywall, the plane of air.\n\nThe Skyborne, the exiles' descendants, have lived here ever since, and the sky has changed them. They have grown slender and light, and a growing share of their children are born with blue skin. Now the wind spirits are gone, and no one on the island can say why. The pylons that hold the island up are failing. Other Skyborne islands are breaking apart, their refugees crowd onto Zephras, and Zephras itself has begun to come apart.\n\nThree powers contend for what is left. The High Order seeks the arcane lore of its Highborne forebears. The Windshapers hold to the old bond with the elements. The Al'Aketh cult serves Al'Akir.",
		source = "",
	},
	[2524] = {
		name = "Darkspear Islands",
		short = "A storm scattered Thrall's stolen fleet as Grand Admiral Daelin Proudmoore's ships chased it across the sea. The damaged orc ships found a cove on a string of islands with an active volcano and put in to mend.",
		full = "A storm scattered Thrall's stolen fleet as Grand Admiral Daelin Proudmoore's ships chased it across the sea. The damaged orc ships found a cove on a string of islands with an active volcano and put in to mend. The Darkspear trolls lived here. They had left Stranglethorn Vale because the other Gurubashi tribes treated them cruelly.\n\nThe witch doctor Sen'jin met the orcs in peace and told Thrall he had seen him in a vision. Sailors of Kul Tiras, stranded from Daelin's fleet, had built an outpost on the islands and were at war with the trolls. During the fighting, murlocs captured Thrall, Sen'jin and the humans and carried them into caverns under the volcano. Thrall fought his way out and reached the murloc altar, but Sen'jin had already been mortally wounded. With his last words he told Thrall that his visions showed Thrall leading the trolls away. The Darkspear sailed after the Horde.\n\nNow the Darkspear Raiders and the Theramore Expeditionary Force fight over the islands.",
		source = "",
	},
	[2548] = {
		name = "Riverglades",
		short = "Stormwind gave up the Riverglades in the First War. The Old Horde overran the region, and the kingdom decided its soldiers were better kept at home.",
		full = "Stormwind gave up the Riverglades in the First War. The Old Horde overran the region, and the kingdom decided its soldiers were better kept at home. For 20 years the knights of the Brotherhood of the Horse have fought to win the land back, and their leader, Demar Brant, thinks the men of Stormwind are cowards hiding behind their walls. Their stronghold is Farholde Keep.\n\nNear the end of the Second War, ogres of the Twilight's Hammer and Stormreaver orcs fled east and joined the ogres already settled here. The main river winds through the land and bends into three oxbow lakes, and goblins sell arms to every side of the standoff.",
		source = "",
	},
	[2652] = {
		name = "Shen'dralas",
		short = "North of Dire Maul lies Shen'dralas, once part of the Highborne city of Eldre'Thalas. Friendly spirits of the Shen'dralar still haunt its ruins.",
		full = "North of Dire Maul lies Shen'dralas, once part of the Highborne city of Eldre'Thalas. Friendly spirits of the Shen'dralar still haunt its ruins. Magram centaurs and Bristleback quilboar claim ground here too. It lies southeast of Desolace, between Feralas and Mulgore.\n\nThe Valley of Bones, a crag on the southern edge of Desolace, belongs to Shen'dralas. Two massive skeletons of unknown origin lie on its floor. Necromancers and undead ravagers walk among the bones, and Magram necromancers roam the north of the land.",
		source = "",
	},
}

SpokenPlaces:RegisterLoreData("enUS", "zones", zones)
